def fatorial(n):
    # 1. Caso Base (Condição de parada obrigatória!)
    if n <= 1:
        return 1
    # 2. Passo Recursivo (reduz n -> n - 1)
    return n * fatorial(n - 1)

print(fatorial(4))  # 4 * 3 * 2 * 1 = 24

